const menuToggle=document.querySelector('.menu-toggle');const navLinks=document.querySelector('.nav-links');menuToggle?.addEventListener('click',()=>navLinks.classList.toggle('open'));document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>navLinks.classList.remove('open')));
const filters=document.querySelectorAll('.filter');const cards=document.querySelectorAll('.project-card');filters.forEach(filter=>filter.addEventListener('click',()=>{filters.forEach(f=>f.classList.remove('active'));filter.classList.add('active');const type=filter.dataset.filter;cards.forEach(card=>card.classList.toggle('hidden',type!=='all'&&card.dataset.type!==type));}));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
